package vn.hoangminh.erp.Ht2Kho.repository; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType; import vn.hoangminh.erp.Ht2Kho.domain.TonKho; import java.util.*; public interface TonKhoRepository extends JpaRepository<TonKho,String> { List<TonKho> findByMaSP(String maSP); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select t from TonKho t where t.maSP=:sp and t.maViTri=:vi") Optional<TonKho> khoa(@Param("sp") String sp,@Param("vi") String vi); }
